CREATE TABLE sfi_result(seq INTEGER,label TEXT,value INTEGER); INSERT INTO sfi_result SELECT 1,'before',count(*) FROM t1; BEGIN; DELETE FROM t1 WHERE (c,d) IN (VALUES(3102,3103),(4102,4103),(5102,5103),(1,2)); ROLLBACK; INSERT INTO sfi_result SELECT 2,'after_rollback',count(*) FROM t1; DELETE FROM t1 WHERE (c,d) IN (VALUES(3102,3103),(4102,4103),(5102,5103),(1,2)); INSERT INTO sfi_result SELECT 3,'after_delete',count(*) FROM t1;